def test_every_pinned_migration_is_present_and_unchanged():
    assert len(PINNED) > 100, "the pin lists too few migrations to be the applied set"
    changed = {}
    for name, digest in PINNED.items():
        path = VERSIONS / name
        assert path.is_file(), f"applied migration {name} is gone (rename or delete): history that runs"
        actual = hashlib.sha256(path.read_bytes()).hexdigest()
        if actual != digest:
            changed[name] = actual
    assert not changed, f"applied migrations edited after they ran: {sorted(changed)}"
